using TMPro;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;

public static class CreateRoomLobbySetup
{
    private static readonly Color Canvas = Hex("#fffaf0");
    private static readonly Color SurfaceCard = Hex("#f5f0e0");
    private static readonly Color Ink = Hex("#0a0a0a");
    private static readonly Color BrandTeal = Hex("#1a3a3a");
    private static readonly Color BrandPink = Hex("#ff4d8b");

    public static string Run()
    {
        var roomCanvas = GameObject.Find("RoomCanvas");
        if (roomCanvas == null) return "RoomCanvas missing";

        var roomUi = Object.FindFirstObjectByType<MultiplayerRoomUI>();
        if (roomUi == null) return "MultiplayerRoomUI missing";

        var lobbyManagerGo = GameObject.Find("LobbyManager");
        if (lobbyManagerGo == null)
        {
            lobbyManagerGo = new GameObject("LobbyManager");
        }

        var networkObject = lobbyManagerGo.GetComponent<NetworkObject>();
        if (networkObject == null) networkObject = lobbyManagerGo.AddComponent<NetworkObject>();
        if (lobbyManagerGo.GetComponent<LobbyManager>() == null) lobbyManagerGo.AddComponent<LobbyManager>();

        var flowGo = GameObject.Find("LobbyFlow");
        if (flowGo == null)
        {
            flowGo = new GameObject("LobbyFlow");
            flowGo.transform.SetParent(roomCanvas.transform, false);
        }

        var flow = flowGo.GetComponent<LobbyFlowController>();
        if (flow == null) flow = flowGo.AddComponent<LobbyFlowController>();

        var nameEntry = EnsureNameEntry(roomCanvas.transform);
        var sidebar = EnsureSidebar(roomCanvas.transform, FindRect(roomUi, "HostPanel"));
        var clientWaiting = EnsureClientWaiting(roomCanvas.transform);

        var flowSo = new SerializedObject(flow);
        flowSo.FindProperty("roomUI").objectReferenceValue = roomUi;
        flowSo.FindProperty("nameEntryUI").objectReferenceValue = nameEntry;
        flowSo.FindProperty("hostSidebarUI").objectReferenceValue = sidebar;
        flowSo.FindProperty("clientWaitingPanel").objectReferenceValue = clientWaiting;
        flowSo.ApplyModifiedPropertiesWithoutUndo();

        EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());
        return "Lobby UI setup complete";
    }

    private static LobbyNameEntryUI EnsureNameEntry(Transform parent)
    {
        var existing = Object.FindFirstObjectByType<LobbyNameEntryUI>();
        if (existing != null) return existing;

        var root = CreatePanel(parent, "NameEntryPanel", new Color(0f, 0f, 0f, 0.45f));
        Stretch(root.GetComponent<RectTransform>());

        var card = CreatePanel(root.transform, "Card", SurfaceCard);
        var cardRect = card.GetComponent<RectTransform>();
        cardRect.anchorMin = cardRect.anchorMax = new Vector2(0.5f, 0.5f);
        cardRect.sizeDelta = new Vector2(560, 320);

        var title = CreateText(card.transform, "Title", "Enter Your Name", 34, FontStyles.Bold, Ink);
        SetAnchored(title.rectTransform, new Vector2(0, 90), new Vector2(480, 50));
        var inputGo = CreateInput(card.transform, "NameInput");
        SetAnchored(inputGo.GetComponent<RectTransform>(), new Vector2(0, 20), new Vector2(420, 64));
        var button = CreateButton(card.transform, "ConfirmNameButton", "CONFIRM", BrandTeal);
        SetAnchored(button.GetComponent<RectTransform>(), new Vector2(0, -80), new Vector2(260, 52));

        var ui = root.AddComponent<LobbyNameEntryUI>();
        var so = new SerializedObject(ui);
        so.FindProperty("root").objectReferenceValue = root;
        so.FindProperty("nameInput").objectReferenceValue = inputGo.GetComponent<TMP_InputField>();
        so.FindProperty("confirmButton").objectReferenceValue = button.GetComponent<Button>();
        so.FindProperty("titleText").objectReferenceValue = title;
        so.FindProperty("hintText").objectReferenceValue = title;
        so.ApplyModifiedPropertiesWithoutUndo();
        root.SetActive(false);
        return ui;
    }

    private static HostLobbySidebarUI EnsureSidebar(Transform parent, RectTransform centerPanel)
    {
        var existing = Object.FindFirstObjectByType<HostLobbySidebarUI>();
        if (existing != null) return existing;

        var sidebar = CreatePanel(parent, "HostSidebar", SurfaceCard);
        var sidebarRect = sidebar.GetComponent<RectTransform>();
        sidebarRect.anchorMin = new Vector2(1f, 0.5f);
        sidebarRect.anchorMax = new Vector2(1f, 0.5f);
        sidebarRect.pivot = new Vector2(1f, 0.5f);
        sidebarRect.sizeDelta = new Vector2(320, 520);
        sidebarRect.anchoredPosition = new Vector2(420f, 0f);

        var title = CreateText(sidebar.transform, "SidebarTitle", "Players", 28, FontStyles.Bold, Ink);
        SetAnchored(title.rectTransform, new Vector2(0, 210), new Vector2(260, 40));

        var listRoot = new GameObject("PlayerList", typeof(RectTransform), typeof(VerticalLayoutGroup));
        listRoot.transform.SetParent(sidebar.transform, false);
        var listRect = listRoot.GetComponent<RectTransform>();
        listRect.anchorMin = new Vector2(0.5f, 0.5f);
        listRect.anchorMax = new Vector2(0.5f, 0.5f);
        listRect.sizeDelta = new Vector2(280, 300);
        listRect.anchoredPosition = new Vector2(0, 20);
        var v = listRoot.GetComponent<VerticalLayoutGroup>();
        v.spacing = 8f;
        v.childAlignment = TextAnchor.UpperCenter;
        v.childControlHeight = true;
        v.childForceExpandHeight = false;

        var overflow = CreateText(sidebar.transform, "OverflowText", "...", 22, FontStyles.Bold, Ink);
        SetAnchored(overflow.rectTransform, new Vector2(0, -170), new Vector2(200, 30));
        overflow.gameObject.SetActive(false);

        var startButton = CreateButton(sidebar.transform, "StartGameButton", "START GAME", BrandPink);
        SetAnchored(startButton.GetComponent<RectTransform>(), new Vector2(0, -220), new Vector2(260, 56));

        var ui = sidebar.AddComponent<HostLobbySidebarUI>();
        var so = new SerializedObject(ui);
        so.FindProperty("centerPanel").objectReferenceValue = centerPanel;
        so.FindProperty("sidebarPanel").objectReferenceValue = sidebarRect;
        so.FindProperty("playerListRoot").objectReferenceValue = listRect;
        so.FindProperty("overflowText").objectReferenceValue = overflow;
        so.FindProperty("startButton").objectReferenceValue = startButton.GetComponent<Button>();
        so.FindProperty("sidebarTitleText").objectReferenceValue = title;
        so.ApplyModifiedPropertiesWithoutUndo();
        sidebar.SetActive(false);
        return ui;
    }

    private static GameObject EnsureClientWaiting(Transform parent)
    {
        var go = GameObject.Find("ClientWaitingPanel");
        if (go != null) return go;

        go = CreatePanel(parent, "ClientWaitingPanel", SurfaceCard);
        var rect = go.GetComponent<RectTransform>();
        rect.anchorMin = rect.anchorMax = new Vector2(0.5f, 0.5f);
        rect.sizeDelta = new Vector2(520, 180);
        CreateText(go.transform, "WaitingText", "Waiting for host to start...", 28, FontStyles.Bold, Ink).alignment = TextAlignmentOptions.Center;
        go.SetActive(false);
        return go;
    }

    private static RectTransform FindRect(MultiplayerRoomUI ui, string childName)
    {
        var hostPanel = ui.transform.Find("HostPanel");
        return hostPanel != null ? hostPanel.GetComponent<RectTransform>() : ui.GetComponent<RectTransform>();
    }

    private static GameObject CreatePanel(Transform parent, string name, Color color)
    {
        var go = new GameObject(name, typeof(RectTransform), typeof(Image));
        go.transform.SetParent(parent, false);
        go.GetComponent<Image>().color = color;
        return go;
    }

    private static TMP_Text CreateText(Transform parent, string name, string text, float size, FontStyles style, Color color)
    {
        var go = new GameObject(name, typeof(RectTransform));
        go.transform.SetParent(parent, false);
        var tmp = go.AddComponent<TextMeshProUGUI>();
        tmp.text = text;
        tmp.fontSize = size;
        tmp.fontStyle = style;
        tmp.color = color;
        tmp.alignment = TextAlignmentOptions.Center;
        return tmp;
    }

    private static GameObject CreateInput(Transform parent, string name)
    {
        var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(TMP_InputField));
        go.transform.SetParent(parent, false);
        go.GetComponent<Image>().color = Canvas;
        var input = go.GetComponent<TMP_InputField>();
        var textGo = new GameObject("Text", typeof(RectTransform));
        textGo.transform.SetParent(go.transform, false);
        var text = textGo.AddComponent<TextMeshProUGUI>();
        text.alignment = TextAlignmentOptions.Center;
        text.fontSize = 30;
        Stretch(text.rectTransform);
        input.textComponent = text;
        input.characterLimit = 16;
        return go;
    }

    private static GameObject CreateButton(Transform parent, string name, string label, Color bg)
    {
        var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(Button));
        go.transform.SetParent(parent, false);
        go.GetComponent<Image>().color = bg;
        var text = CreateText(go.transform, "Text", label, 18, FontStyles.Bold, Color.white);
        Stretch(text.rectTransform);
        return go;
    }

    private static void Stretch(RectTransform rect)
    {
        rect.anchorMin = Vector2.zero;
        rect.anchorMax = Vector2.one;
        rect.offsetMin = Vector2.zero;
        rect.offsetMax = Vector2.zero;
    }

    private static void SetAnchored(RectTransform rect, Vector2 pos, Vector2 size)
    {
        rect.anchorMin = rect.anchorMax = new Vector2(0.5f, 0.5f);
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.anchoredPosition = pos;
        rect.sizeDelta = size;
    }

    private static Color Hex(string hex)
    {
        return ColorUtility.TryParseHtmlString(hex, out var color) ? color : Color.white;
    }
}
